package sql

import (
	"crypto/rand"
	"fmt"
)

// newUUID generates a random (v4) UUID for Database.nextId() — fiig IDs
// are opaque strings (`value CustomerId: string`), generated by the
// capability itself rather than by the database (no auto-increment
// column, no driver-specific RETURNING/LAST_INSERT_ID() dance to
// abstract over), so a UUID is both portable across any SQL engine and
// matches the language's own modeling choice. No third-party dependency
// needed for this — 16 random bytes plus RFC 4122's version/variant bits
// is all a v4 UUID is.
func newUUID() (string, error) {
	var b [16]byte
	if _, err := rand.Read(b[:]); err != nil {
		return "", err
	}
	b[6] = (b[6] & 0x0f) | 0x40 // version 4
	b[8] = (b[8] & 0x3f) | 0x80 // variant 10
	return fmt.Sprintf("%x-%x-%x-%x-%x", b[0:4], b[4:6], b[6:8], b[8:10], b[10:16]), nil
}
